int main(int argc, char const *argv[]) {
  Mongo_replayPlugin plugin;
  json output, params;

  // Set example values to params
  params["db_uri"] = "mongodb://jakku.dii.unitn.it:27017/";
  params["db_name"] = "miroscic";
  params["collections"] = {"arduino_dashboard", "hpe_out"};
  params["start_time"] = "2025-01-01T00:00:00Z";
  params["max_loop_duration_ms"] = 1000;
  
  // Set the parameters
  plugin.set_params(params);

  for (const auto &item : plugin.info()) {
    cout << item.first << ": " << item.second << endl;
  }
  
  // Process data
  for (size_t i = 0; i < 10; i++) {
    plugin.get_output(output);
    cout << "Output: " << output.dump() << endl;
    cout << "Next loop in: " << plugin.next_loop_duration.count() << " ms" << endl;
  }

  // Produce output
  cout << "Output: " << output << endl;

  return 0;
}
